1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    /* Dark enough to keep 3:1 against --bg at the resting 0.85 opacity */
31	    [data-color="green"] { --fg: #15803d; }
32	    [data-color="amber"] { --fg: #b45309; }
33	    [data-color="violet"] { --fg: #7c3aed; }
34	    [data-color="cyan"] { --fg: #0e7490; }
35	    @media (prefers-color-scheme: dark) {
36	      :root {
37	        --bg: #111;
38	        --text: #d1d5db;
39	        --fg: #93c5fd;
40	        --shadow: rgba(0, 0, 0, 0.6);
41	        --kbd-bg: rgba(255, 255, 255, 0.15);
42	      }
43	      [data-color="red"] { --fg: #fca5a5; }
44	      [data-color="green"] { --fg: #86efac; }
45	      [data-color="amber"] { --fg: #fcd34d; }
46	      [data-color="violet"] { --fg: #c4b5fd; }
47	      [data-color="cyan"] { --fg: #67e8f9; }
48	    }
49	    @media (prefers-contrast: more) {
50	      :root {
51	        --shadow: rgba(0, 0, 0, 0.9);
52	        --drop: drop-shadow(0 2px 8px var(--shadow));
53	      }
54	      .circle svg {
55	        opacity: 1;
56	      }
57	    }
58	    @media (forced-colors: active) {
59	      /* The color is the content here, so keep it; the stroke guarantees the shape */
60	      .circle svg {
61	        forced-color-adjust: none;
62	        color: var(--fg);
63	      }
64	      svg circle {
65	        stroke: CanvasText;
66	        stroke-width: 2;
67	      }
68	    }
69	    body {
70	      min-height: 100vh;
71	      min-height: 100dvh;
72	      display: grid;
73	      place-items: center;
74	      padding: 1rem;
75	      background: var(--bg);
76	      color: var(--text);
77	      font-family: system-ui, -apple-system, sans-serif;
78	    }
79	    main {
80	      width: 100%;
81	      display: flex;
82	      flex-direction: column;
83	      align-items: center;
84	      text-align: center;
85	    }
86	    .circle {
87	      display: block;
88	      width: min(360px, 100%, 60vh);
89	      aspect-ratio: 1;
90	      border: 0;
91	      border-radius: 50%;
92	      background: none;
93	      color: var(--fg);
94	      cursor: pointer;
95	      touch-action: manipulation;
96	      -webkit-tap-highlight-color: transparent;
97	      -webkit-user-select: none;
98	      user-select: none;
99	      -webkit-touch-callout: none;
100	      transition: color 0.4s;
101	      min-height: 48px;
102	      min-width: 48px;
103	    }
104	    .no-transition,
105	    .no-transition svg {
106	      transition: none !important;
107	    }
108	    .circle:focus-visible {
109	      outline: 3px solid currentColor;
110	      outline-offset: 12px;
111	    }
112	    svg {
113	      display: block;
114	      width: 100%;
115	      height: 100%;
116	      overflow: visible;
117	      /* Leave hit testing to the button's rounded box, not the svg's square one */
118	      pointer-events: none;
119	      opacity: 0.85;
120	      filter: var(--drop);
121	      transition: opacity 0.3s;
122	    }
123	    .circle:active svg,
124	    .circle:focus-visible svg {
125	      opacity: 1;
126	    }
127	    @keyframes pulse {
128	      0% {
129	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
130	      }
131	      100% {
132	        filter: var(--drop) drop-shadow(0 0 0 transparent);
133	      }
134	    }
135	    @media (hover: hover) {
136	      .circle:hover svg {
137	        opacity: 1;
138	      }
139	    }
140	    @media (prefers-reduced-motion: no-preference) {
141	      svg {
142	        transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.3s;
143	      }
144	      .circle:focus-visible svg {
145	        transform: scale(1.05);
146	      }
147	      .circle:active svg {
148	        transform: scale(0.97);
149	      }
150	      .circle.color-changed svg {
151	        animation: pulse 0.5s ease-out;
152	      }
153	    }
154	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
155	      .circle:hover:not(:active) svg {
156	        transform: scale(1.05);
157	      }
158	    }
159	    .visually-hidden {
160	      position: absolute;
161	      width: 1px;
162	      height: 1px;
163	      overflow: hidden;
164	      clip-path: inset(50%);
165	      white-space: nowrap;
166	    }
167	    .status {
168	      margin-top: 2rem;
169	      font-weight: 600;
170	    }
171	    .hint {
172	      margin-top: 0.25rem;
173	      font-size: 0.875rem;
174	      line-height: 1.75;
175	      text-wrap: balance;
176	    }
177	    .help-button {
178	      margin-left: 0.5rem;
179	      display: inline-block;
180	      width: 1.5rem;
181	      height: 1.5rem;
182	      border-radius: 50%;
183	      background: var(--kbd-bg);
184	      border: 1px solid var(--text);
185	      color: var(--text);
186	      cursor: pointer;
187	      font: inherit;
188	      font-size: 0.75rem;
189	      font-weight: bold;
190	      line-height: 1;
191	      text-align: center;
192	      vertical-align: middle;
193	      touch-action: manipulation;
194	      transition: background-color 0.2s, color 0.2s;
195	    }
196	    .help-button:focus-visible {
197	      outline: 2px solid currentColor;
198	      outline-offset: 2px;
199	    }
200	    @media (hover: hover) {
201	      .help-button:hover {
202	        background: var(--text);
203	        color: var(--bg);
204	      }
205	    }
206	    .keys {
207	      display: none;
208	    }
209	    .keys.visible {
210	      display: inline;
211	    }
212	    @media (hover: none) and (pointer: coarse) {
213	      .hint .keys {
214	        display: none !important;
215	      }
216	      .help-button {
217	        display: none;
218	      }
219	    }
220	    kbd {
221	      display: inline-block;
222	      padding: 0.125rem 0.375rem;
223	      background: var(--kbd-bg);
224	      border: 1px solid transparent;
225	      border-radius: 0.25rem;
226	      font-family: monospace;
227	      font-size: 0.75em;
228	      line-height: 1.2;
229	    }
230	  </style>
231	</head>
232	<body>
233	  <main>
234	    <h1 class="visually-hidden">Animated Circle</h1>
235	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
236	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
237	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
238	      </svg>
239	    </button>
240	    <p class="status" id="status" role="status" aria-live="polite">Blue</p>
241	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
242	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
243	  </main>
244	  <script>
245	    const config = {
246	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
247	      storageKey: 'circle-color',
248	      hapticDuration: 50,
249	      longPressDuration: 500,
250	      longPressTolerance: 10,
251	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
252	    };
253	
254	    const DOM = {
255	      button: document.querySelector('.circle'),
256	      status: document.querySelector('.status'),
257	      helpButton: document.querySelector('.help-button'),
258	      keyHint: document.querySelector('.keys'),
259	      verbSpan: document.querySelector('.verb'),
260	      doubleVerbSpan: document.querySelector('.double-verb'),
261	    };
262	
263	    const state = {
264	      index: 0,
265	      shiftHeld: false,
266	      hoverCapable: true,
267	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
268	      hoverQuery: matchMedia('(hover: none)'),
269	      longPressTimer: null,
270	      longPressed: false,
271	      pressX: 0,
272	      pressY: 0,
273	      pointerType: '',
274	    };
275	
276	    function loadColor() {
277	      try {
278	        return localStorage.getItem(config.storageKey);
279	      } catch {
280	        return null;
281	      }
282	    }
283	
284	    function saveColor(color) {
285	      try {
286	        localStorage.setItem(config.storageKey, color);
287	      } catch {}
288	    }
289	
290	    function applyColor() {
291	      const color = config.colors[state.index];
292	      // The first color is the :root default, so it needs no attribute
293	      if (state.index === 0) delete DOM.button.dataset.color;
294	      else DOM.button.dataset.color = color;
295	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
296	    }
297	
298	    function syncFromStorage(color = loadColor()) {
299	      const index = config.colors.indexOf(color);
300	      state.index = index === -1 ? 0 : index;
301	      applyColor();
302	    }
303	
304	    // acknowledge: give feedback even when the color is already the requested one
305	    function setIndex(next, { haptic = false, acknowledge = false } = {}) {
306	      const changed = next !== state.index;
307	      if (!changed && !acknowledge) return;
308	      if (changed) {
309	        state.index = next;
310	        applyColor();
311	        saveColor(config.colors[state.index]);
312	      }
313	
314	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
315	
316	      if (state.reducedMotion.matches) return;
317	      DOM.button.classList.remove('color-changed');
318	      void DOM.button.offsetWidth;
319	      DOM.button.classList.add('color-changed');
320	    }
321	
322	    function changeColor(step) {
323	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
324	    }
325	
326	    function updateDeviceVerbs() {
327	      state.hoverCapable = !state.hoverQuery.matches;
328	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
329	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
330	    }
331	
332	    function toggleKeyHintVisibility() {
333	      const expanded = DOM.keyHint.classList.toggle('visible');
334	      DOM.helpButton.setAttribute('aria-expanded', expanded);
335	    }
336	
337	    function syncKeyHint() {
338	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
339	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
340	    }
341	
342	    function handleKeyDown(event) {
343	      if (event.key === 'Enter' || event.key === ' ') {
344	        if (!event.repeat) state.shiftHeld = event.shiftKey;
345	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
346	        return;
347	      }
348	
349	      if (event.altKey || event.ctrlKey || event.metaKey) return;
350	
351	      if (event.key in config.keySteps) {
352	        event.preventDefault();
353	        changeColor(config.keySteps[event.key]);
354	      } else if (event.key === 'Home') {
355	        event.preventDefault();
356	        setIndex(0, { haptic: true });
357	      } else if (event.key === 'End') {
358	        event.preventDefault();
359	        setIndex(config.colors.length - 1, { haptic: true });
360	      }
361	    }
362	
363	    function handleEscape(event) {
364	      if (event.key !== 'Escape' || state.hoverCapable) return;
365	      if (DOM.keyHint.classList.contains('visible')) toggleKeyHintVisibility();
366	    }
367	
368	    // Initialize
369	    syncFromStorage();
370	
371	    // Wait two frames to ensure layout is complete before enabling transitions
372	    requestAnimationFrame(() => requestAnimationFrame(() => {
373	      DOM.button.classList.remove('no-transition');
374	    }));
375	
376	    updateDeviceVerbs();
377	    syncKeyHint();
378	    // e.g. a tablet gaining or losing a trackpad/keyboard
379	    state.hoverQuery.addEventListener('change', () => {
380	      updateDeviceVerbs();
381	      syncKeyHint();
382	    });
383	
384	    // Event listeners
385	    function clearLongPressTimer() {
386	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
387	      state.longPressTimer = null;
388	    }
389	
390	    function attachEventListeners() {
391	      DOM.button.addEventListener('keydown', handleKeyDown);
392	      DOM.button.addEventListener('keyup', (event) => {
393	        if (event.key === ' ') state.shiftHeld = event.shiftKey;
394	      });
395	      DOM.button.addEventListener('blur', () => {
396	        state.shiftHeld = false;
397	        clearLongPressTimer();
398	      });
399	      DOM.button.addEventListener('pointerdown', (event) => {
400	        clearLongPressTimer();
401	        state.longPressed = false;
402	        state.pointerType = event.pointerType;
403	        if (!event.isPrimary || event.button !== 0) return;
404	        state.pressX = event.clientX;
405	        state.pressY = event.clientY;
406	        state.longPressTimer = setTimeout(() => {
407	          state.longPressTimer = null;
408	          state.longPressed = true;
409	          setIndex(0, { haptic: true, acknowledge: true });
410	        }, config.longPressDuration);
411	      }, { passive: true });
412	      // Touch pointers are captured, so a finger sliding away never fires pointerleave
413	      DOM.button.addEventListener('pointermove', (event) => {
414	        if (!state.longPressTimer) return;
415	        const distance = Math.hypot(event.clientX - state.pressX, event.clientY - state.pressY);
416	        if (distance > config.longPressTolerance) clearLongPressTimer();
417	      }, { passive: true });
418	      DOM.button.addEventListener('contextmenu', (event) => {
419	        if (state.pointerType === 'mouse') {
420	          clearLongPressTimer();
421	        } else if (state.longPressTimer || state.longPressed) {
422	          event.preventDefault();
423	        }
424	      });
425	      DOM.button.addEventListener('pointerup', clearLongPressTimer, { passive: true });
426	      DOM.button.addEventListener('pointercancel', clearLongPressTimer, { passive: true });
427	      DOM.button.addEventListener('pointerleave', clearLongPressTimer, { passive: true });
428	      DOM.button.addEventListener('click', (event) => {
429	        clearLongPressTimer();
430	        const afterLongPress = state.longPressed && event.detail !== 0;
431	        state.longPressed = false;
432	        const reverse = event.shiftKey || state.shiftHeld;
433	        state.shiftHeld = false;
434	        if (afterLongPress || event.detail > 1) return;
435	        changeColor(reverse ? -1 : 1);
436	      });
437	      DOM.button.addEventListener('dblclick', () => {
438	        setIndex(0, { haptic: true, acknowledge: true });
439	      });
440	      DOM.button.addEventListener('animationend', () => {
441	        DOM.button.classList.remove('color-changed');
442	      });
443	
444	      DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
445	      addEventListener('keydown', handleEscape);
446	    }
447	
448	    attachEventListeners();
449	
450	    addEventListener('storage', (event) => {
451	      // Sync if changed key matches or if entire storage was cleared (key === null)
452	      if (event.key !== config.storageKey && event.key !== null) return;
453	      syncFromStorage(event.newValue);
454	    });
455	    // Storage events are not delivered while the page sits in the bfcache
456	    addEventListener('pageshow', (event) => {
457	      if (event.persisted) syncFromStorage();
458	    });
459	  </script>
460	</body>
461	</html>
